    <Chart3DPrimaryYAxis Title="Users" ValueType="Syncfusion.Blazor.Chart3D.ValueType.Double" Interval="10">
        <Chart3DAxisMajorGridLines Color="red" Width="2"></Chart3DAxisMajorGridLines>
