 The following example demonstrates how to define a custom expand icon template:

 <SfDiagramComponent Height="600px" Nodes="@nodes" Connectors="@connectors">
  <DiagramTemplates>
     <DiagramExpandIconTemplate> 
     @{
         <div style="height: 100%; width: 100%">
             <input type="button" value="Collapse" />
         </div>
       } 
      </DiagramExpandIconTemplate>
   </DiagramTemplates>
  </SfDiagramComponent>
 @code {
    DiagramObjectCollection<Node> nodes = new DiagramObjectCollection<Node>();
    DiagramObjectCollection<Connector> connectors = new DiagramObjectCollection<Connector>();
    protected override void OnInitialized()
    {
         nodes = new DiagramObjectCollection<Node>(){};
         connectors = new DiagramObjectCollection<Connector>(){};
         Node node1 = new Node()
         {
             ID = "node1",
             Width = 100,
             Height = 100,
             OffsetX = 300, 
             OffsetY = 100,
             ExpandIcon = new DiagramExpandIcon()
             {
                 Shape = DiagramExpandIcons.Template,
                 Height = 20,
                 Width = 20,
             },
             CollapseIcon = new DiagramCollapseIcon()
             {
                 Shape = DiagramCollapseIcons.Template,
                 Height = 20,
                 Width = 20,
              },
          };
          nodes.Add(node1);
          Node node2 = new Node()
          {
             ID = "node2",
             Width = 100,
             Height = 100,
             OffsetX = 300,
             OffsetY = 400,
             ExpandIcon = new DiagramExpandIcon()
             { 
                 Shape = DiagramExpandIcons.Template,
                 Height = 20,
                 Width = 20,
             },
             CollapseIcon = new DiagramCollapseIcon()
             {
                Shape = DiagramCollapseIcons.Template,
                Height = 20,
                Width = 20,
             },
         };
         nodes.Add(node2);
         Connector connector1 = new Connector()
         {
            ID = "connector1",
            SourceID = "node1",
            TargetID = "node2",
         };
         connectors.Add(connector1);
    }
}

