member.example:
The following example demonstrates both refresh modes of the  method in a Blazor application with user-triggered refresh scenarios:

@page "/pivot-refresh-example"
@using Syncfusion.Blazor.PivotView
@using Microsoft.AspNetCore.Components.Web

<h3>Pivot Table with Refresh Modes</h3>

<div class="mb-3">
    <button class="btn btn-secondary" @onclick="RefreshLayoutOnly">
        Refresh Layout Only
    </button>
    <button class="btn btn-primary ms-2" @onclick="RefreshWithData">
        Refresh Data & Layout
    </button>
</div>

<SfPivotView @ref="pivotView"  
             TValue="ProductDetails"  
             DataSource="@ProductData"
             Height="400">
    <PivotViewDataSourceSettings>
        <PivotViewColumns>
            <PivotViewColumn Name="Country"></PivotViewColumn>
            <PivotViewColumn Name="Year"></PivotViewColumn>
        </PivotViewColumns>
        <PivotViewRows>
            <PivotViewRow Name="Products"></PivotViewRow>
        </PivotViewRows>
        <PivotViewValues>
            <PivotViewValue Name="Sold" Caption="Units Sold"></PivotViewValue>
            <PivotViewValue Name="Amount" Caption="Sales Amount"></PivotViewValue>
        </PivotViewValues>
    </PivotViewDataSourceSettings>
</SfPivotView>

@code {
    private SfPivotView<ProductDetails> pivotView;
    private List<ProductDetails> ProductData = new List<ProductDetails>();

    protected override void OnInitialized()
    {
        ProductData = GetProductData();
    }

    // Layout-only refresh - fast operation for UI updates
    private async Task RefreshLayoutOnly()
    {
        try
        {
            await pivotView.RefreshAsync(); // Default: allowDataRefresh = false
        }
        catch (InvalidOperationException ex)
        {
            Console.WriteLine($"Layout refresh error: {ex.Message}");
        }
    }

    // Update data source and refresh
    private async Task RefreshWithData()
    {
        try
        {
            // Modify the data source
            ProductData.Add(new ProductDetails  
            {  
                Products = "New Product",  
                Country = "USA",  
                Year = "2024",  
                Sold = 100,  
                Amount = 5000  
            });

            // Perform full refresh to include new data
            await pivotView.RefreshAsync(true);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Update and refresh error: {ex.Message}");
        }
    }

    private List<ProductDetails> GetProductData()
    {
        return new List<ProductDetails>
        {
            new ProductDetails { Products = "Bike", Country = "USA", Year = "2023", Sold = 25, Amount = 1250 },
            new ProductDetails { Products = "Car", Country = "UK", Year = "2023", Sold = 15, Amount = 7500 }
        };
    }
    public class ProductDetails
    {
        public string Products { get; set; }
        public string Country { get; set; }
        public string Year { get; set; }
        public int Sold { get; set; }
        public decimal Amount { get; set; }
    }
}

